        "5": "白はもう1本のポーンで中央を押し広げます。",
        "6": "黒のビショップがf3のナイトにからみます。",
        "7": "白はe5のポーンを取ります。",
        "8": "黒はビショップでナイトを取ります。でもこれで、黒は駒の出足で遅れはじめます。",
        "9": "クイーンで取り返します。白のクイーンは早くも働きはじめました。",
