        "14": "黒はクイーンでf7を守ります。b7のポーンは取られてもいい、という判断です。",
        "15": "モーフィーはポーンを取らずに、ナイトを出しました。駒の数より、駒を早く働かせることを選んだ一手です。",
        "16": "黒はc6で守りを固めます。",
        "17": "ビショップがf6のナイトをピンします。ナイトが動くと、うしろのクイーンが取られてしまいます。",
        "18": "黒はポーンでビショップを追い払おうとします。",
