        "13": "白はビショップを間に入れてチェックを防ぎます。",
        "14": "黒はポーンを取り返しました。しかも、このクイーンはe列でe4のナイトとキングを一直線に見ています。ナイトが動くと、キングがチェックされてしまいます。",
        "15": "白はクイーン側にキャスリング。キングがe列から逃げ、ルークがd1に来ました。d1のルーク、d3のクイーン、そして黒のキングのそばのd8が一列に並びます。",
